// plugins/parley/src/rpc.ts
import { Rpc } from "@opencode/plugin/rpc";
var RPC_ID = "parley";
var ParleyRpc = Rpc.define({
  id: RPC_ID,
  methods: {
    attach: {
      input: {
        type: "object",
        required: ["clientID"],
        properties: {
          clientID: { type: "string" },
          sessionIDs: { type: "array", items: { type: "string" } },
          detach: { type: "boolean" }
        }
      },
      output: { type: "object" }
    },
    pending: {
      input: { type: "object", properties: { sessionID: { type: "string" } } },
      output: { type: "object" }
    },
    submit: {
      input: {
        type: "object",
        required: ["roundID", "answers"],
        properties: {
          roundID: { type: "string" },
          answers: { type: "array", items: { type: "object" } },
          final: { type: "boolean" }
        }
      },
      output: { type: "object" }
    },
    cancel: {
      input: {
        type: "object",
        required: ["roundID"],
        properties: { roundID: { type: "string" }, reason: { type: "string" } }
      },
      output: { type: "object" }
    }
  },
  events: {
    round: {
      schema: {
        type: "object",
        required: ["sessionID", "roundID", "action"],
        properties: {
          sessionID: { type: "string" },
          roundID: { type: "string" },
          action: { type: "string", enum: ["opened", "updated", "closed", "ended", "native"] },
          status: { type: "string" },
          reason: { type: "string" },
          message: { type: "string" },
          callID: { type: "string" }
        }
      }
    }
  }
});

